# ----------------------------------------------------------------------
# configuration (secrets -> env -> UI overrides)
# ----------------------------------------------------------------------
def secrets_dict():
    try:
        return dict(st.secrets)
    except Exception:
        return {}


def build_config() -> Config:
    cfg = Config.from_sources(secrets_dict())
    s = st.session_state
    cfg.dhan_client_id = s.get("ui_dhan_id", cfg.dhan_client_id) or ""
    cfg.dhan_access_token = s.get("ui_dhan_token", cfg.dhan_access_token) or ""
    cfg.dhan_enabled = bool(cfg.dhan_client_id and cfg.dhan_access_token)
    cfg.dhan_ws_enabled = bool(s.get("ui_dhan_ws", cfg.dhan_ws_enabled))
    if s.get("ui_llm_provider"):
        cfg.llm_provider = s["ui_llm_provider"]
    if s.get("ui_llm_key"):
        cfg.llm_api_key = s["ui_llm_key"]
    if s.get("ui_llm_model"):
        cfg.llm_model = s["ui_llm_model"]
    cfg.ai_mode = "paid" if (cfg.llm_provider and cfg.llm_api_key) else "free"
    cfg.refresh_seconds = int(s.get("ui_refresh", cfg.refresh_seconds))
    cfg.capital = float(s.get("ui_capital", cfg.capital))
    cfg.risk_per_trade_pct = float(s.get("ui_risk", cfg.risk_per_trade_pct))
    cfg.zone_target_rr = float(s.get("ui_rr", cfg.zone_target_rr))
    cfg.zone_legout_mult = float(s.get("ui_legout", cfg.zone_legout_mult))
    cfg.zone_max_wick_pct = float(s.get("ui_wick", cfg.zone_max_wick_pct))
    cfg.zone_sl_buffer_atr = float(s.get("ui_slbuf", cfg.zone_sl_buffer_atr))
    cfg.zone_eod_filter = bool(s.get("ui_eod", cfg.zone_eod_filter))
    cfg.yahoo_enabled = bool(s.get("ui_yahoo", cfg.yahoo_enabled))
    cfg.nse_enabled = bool(s.get("ui_nse", cfg.nse_enabled))
    cfg.news_enabled = bool(s.get("ui_news", cfg.news_enabled))

    # --- news intelligence ------------------------------------------------
    cfg.firecrawl_api_key = s.get("ui_fc_key", cfg.firecrawl_api_key) or ""
    cfg.firecrawl_enabled = bool(s.get("ui_fc_on", bool(cfg.firecrawl_api_key)))
    cfg.huginn_base_url = s.get("ui_huginn_url", cfg.huginn_base_url) or ""
    cfg.huginn_token = s.get("ui_huginn_token", cfg.huginn_token) or ""
    cfg.huginn_webhook_url = s.get("ui_huginn_hook", cfg.huginn_webhook_url) or ""
    cfg.huginn_enabled = bool(s.get("ui_huginn_on", bool(cfg.huginn_base_url)))

    # --- alerts / execution ----------------------------------------------
    cfg.alerts_enabled = bool(s.get("ui_alerts_on", cfg.alerts_enabled))
    cfg.telegram_bot_token = s.get("ui_tg_token", cfg.telegram_bot_token) or ""
    cfg.telegram_chat_id = s.get("ui_tg_chat", cfg.telegram_chat_id) or ""
    cfg.webhook_url = s.get("ui_webhook", cfg.webhook_url) or ""
    cfg.alert_cooldown_min = int(s.get("ui_cooldown", cfg.alert_cooldown_min))
    cfg.alert_max_per_cycle = int(s.get("ui_max_cycle", cfg.alert_max_per_cycle))
    cfg.alert_max_per_hour = int(s.get("ui_max_hour", cfg.alert_max_per_hour))
    cfg.score_alert_threshold = int(s.get("ui_score_thr", cfg.score_alert_threshold))
    cfg.news_alert_symbols = s.get("ui_alert_syms", cfg.news_alert_symbols) or ""
    cfg.auto_trade_enabled = bool(s.get("ui_auto_trade", cfg.auto_trade_enabled))
    cfg.auto_trade_armed = bool(s.get("ui_armed", False))
    cfg.auto_trade_max_orders_day = int(s.get("ui_max_orders", cfg.auto_trade_max_orders_day))
    cfg.auto_trade_max_notional = float(s.get("ui_max_notional", cfg.auto_trade_max_notional))
    cfg.auto_trade_product = s.get("ui_product", cfg.auto_trade_product) or "INTRADAY"
    cfg.auto_trade_exchange = s.get("ui_exchange", cfg.auto_trade_exchange) or "NSE_FNO"
    return cfg


# ----------------------------------------------------------------------
# cycle runners
# ----------------------------------------------------------------------
def run_cycle(cfg: Config, force: bool = False):
    s = st.session_state
    now = time.time()
    stale = now - float(s.get("last_run", 0)) > max(5, cfg.refresh_seconds)
    if not force and s.get("state") is not None and not stale:
        return s["state"]
    orch = Orchestrator(cfg)
    universe = s.get("universe", FNO_UNIVERSE)
    rules = dict(st.session_state.get("ui_rules", {}))
    with st.spinner("Agents working: ingest → derivatives → news → alerts …"):
        state = orch.run(universe, zone_timeframes=[], zone_symbols=[], run_zone=False,
                         alert_rules=rules, auto_trade=bool(st.session_state.get("ui_auto_trade", False)))
    s["orch"], s["state"], s["last_run"] = orch, state, now
    s["zone_dirty"] = True
    return state


def run_zone_scan(cfg: Config):
    s = st.session_state
    state = s.get("state")
    if state is None:
        return
    tfs = s.get("ui_tfs", ["15m", "1h", "1d"])
    scope = s.get("ui_scope", "Top 40 by |AI score|")
    if scope.startswith("Top"):
        try:
            n = int(scope.split()[1])
        except Exception:
            n = 40
        syms = [f["Symbol"] for f in sorted(state.features, key=lambda f: -abs(f["Raw_Score"]))[:n]]
    elif scope == "Watchlist":
        wl = [x.strip().upper() for x in s.get("ui_watchlist", "").split(",") if x.strip()]
        syms = wl or [f["Symbol"] for f in state.features[:25]]
    else:
        syms = [f["Symbol"] for f in state.features]
    with st.spinner(f"Zone Agent scanning {len(syms)} symbols × {len(tfs)} timeframes …"):
        rep = ZoneAgent(cfg).run(state, timeframes=list(tfs), symbols=syms,
                                 max_symbols=len(syms))
        rrep = RiskAgent(cfg).run(state)
    from terminal.agents.alert_agent import AlertAgent
    arep = AlertAgent(cfg).run(state, enabled_rules=dict(s.get("ui_rules", {})),
                               auto_trade=bool(s.get("ui_auto_trade", False)))
    s["orch"].reports[rep.name] = rep
    s["orch"].reports[rrep.name] = rrep
    s["orch"].reports[arep.name] = arep
    s["zone_dirty"] = False


def global_zone_rows(cfg: Config):
    """Zones for commodities / indices / FX from real Yahoo candles."""
    s = st.session_state
    cached = s.get("global_rows")
    if cached and time.time() - cached[0] < 600:
        return cached[1]
    yh = YahooProvider(cfg)
    rows = []
    if yh.is_available():
        from terminal.services.candles import CandleService
        svc = CandleService(yh, cache_dir=f"{cfg.cache_dir}/candles")
        for inst in GLOBAL_INSTRUMENTS:
            df = svc.get(inst["yahoo"], "1h")
            if df is None or df.empty:
                continue
            spot = 0.0
            q = s.get("state").global_quotes.get(inst["key"]) if s.get("state") else None
            spot = q.ltp if q else float(df["close"].iloc[-1])
            zones = detect_zones(df, spot=spot, max_zones=1,
                                 legout_mult=cfg.zone_legout_mult,
                                 max_wick_pct=cfg.zone_max_wick_pct,
                                 tight_base=cfg.zone_eod_filter)
            if not zones:
                continue
            e20, e50 = ema(df, 20), ema(df, 50)
            bias = "BUY" if (spot > e20 > 0 and (e50 == 0 or e20 > e50)) else (
                "SELL" if (spot < e20 and (e50 == 0 or e20 < e50)) else "AVOID TRADE")
            row = build_zone_row(inst["key"], "1h", zones[0], spot, spot,
                                 rr=cfg.zone_target_rr, sl_buffer_atr=cfg.zone_sl_buffer_atr,
                                 capital=cfg.capital, risk_pct=cfg.risk_per_trade_pct,
                                 ai_score=f"{int(max(-10, min(10, round((rsi(df,14)-50)/5))))}/10",
                                 ai_bias=bias)
            row["Near Timeframe"] = "1h"
            rows.append(row)
    s["global_rows"] = (time.time(), rows)
    return rows


