        st.caption("स्पॉट LTP अब सिर्फ़ नंबर है (गलती से टैप होकर चार्ट नहीं खुलेगा)। "
                   "चार्ट के लिए नीचे बड़े बटन या '📈 फ्यूचर्स' कॉलम दबाएँ।")
