with tab_news:
    st.markdown("### 📰 NEWS & EVENTS")
    st.caption("RSS scraping + Huginn events + Firecrawl deep search → सिर्फ वही खबरें जो "
               "आपके NSE F&O universe या global instruments को affect करती हैं।")

    render_events(UNIVERSE, max_news=20)
    st.markdown("---")

    news = state.news or []
    meta = (state.notes or {}).get("news_meta", {})
    health_strip(meta)
    if news:
        summary_row(news)
    _b = state.breadth or {}
    if _b.get("Total"):
        st.markdown(
            f'<span class="chip chip-bull">{_b.get("Advances", 0)} advancing</span>'
            f'<span class="chip chip-bear">{_b.get("Declines", 0)} declining</span>'
            f'<span class="chip">{_b.get("Gap-Up", 0)} gap-up · {_b.get("Gap-Down", 0)} gap-down</span>'
            f'<span class="chip">{_b.get("Total", 0)} F&amp;O names</span>',
            unsafe_allow_html=True)

    # ---------------- source settings (collapsed) ----------------------
    with st.expander("🔧 News sources — Firecrawl / Huginn (optional)", expanded=False):
        n1, n2 = st.columns(2)
        with n1:
            st.session_state["ui_fc_on"] = st.toggle(
                "Firecrawl deep search", value=bool(cfg.firecrawl_enabled),
                help="Symbol-wise web search. Free key: firecrawl.dev. "
                     f"Budget {cfg.firecrawl_queries_per_cycle} queries/cycle, cached 30 min.")
            st.session_state["ui_fc_key"] = st.text_input(
                "Firecrawl API key", value=st.session_state.get("ui_fc_key", ""),
                type="password", placeholder="fc-…")
        with n2:
            st.session_state["ui_huginn_on"] = st.toggle(
                "Huginn events", value=bool(cfg.huginn_enabled),
                help="Pull events from your self-hosted Huginn instance.")
            st.session_state["ui_huginn_url"] = st.text_input(
                "Huginn base URL", value=st.session_state.get("ui_huginn_url",
                                                              cfg.huginn_base_url),
                placeholder="http://localhost:3000")
            st.session_state["ui_huginn_token"] = st.text_input(
                "Huginn token", value=st.session_state.get("ui_huginn_token", ""),
                type="password")
        st.caption("बिना key भी RSS scraping पूरा काम करता है — Firecrawl/Huginn सिर्फ extra "
                   "symbol-level depth और अपने scrapers जोड़ने के लिए हैं।")

    if not news:
        st.warning("इस cycle में कोई feed reachable नहीं थी। नीचे Deep search से सीधे "
                   "किसी symbol की खबर खींच सकते हैं (Firecrawl key चाहिए)।")
    else:
        # ---------------- filters -------------------------------------
        sym_counts = {}
        for n in news:
            for sym in (n.get("Symbols") or []):
                sym_counts[sym] = sym_counts.get(sym, 0) + 1
        hot = sorted(sym_counts, key=lambda k: -sym_counts[k])

        f1, f2, f3 = st.columns([1.3, 1.2, 1])
        with f1:
            scope = st.radio("दिखाएँ", ["Relevant only", "All"], horizontal=True,
                             index=0, key="news_scope")
        with f2:
            pick = st.multiselect("Symbol", hot[:80], default=[], key="news_syms",
                                  placeholder="किसी भी F&O नाम की खबर")
        with f3:
            gpick = st.multiselect("Instrument", sorted({g for n in news
                                                         for g in (n.get("Globals") or [])}),
                                   default=[], key="news_globs",
                                   format_func=lambda k: GLOBAL_LABEL.get(k, k))

        items = news if scope == "All" else [n for n in news if n.get("Relevant")]
        if pick:
            items = [n for n in items if set(n.get("Symbols") or []) & set(pick)]
        if gpick:
            items = [n for n in items if set(n.get("Globals") or []) & set(gpick)]

        t_feed, t_hot, t_inst, t_macro, t_search = st.tabs(
            ["📌 Feed", "🔥 By symbol", "🌐 Instruments", "🌍 Macro", "🔎 Deep search"])

        with t_feed:
            st.markdown(f"**{len(items)} headlines**" +
                        (f" · filters: {', '.join(pick + gpick)}" if (pick or gpick) else ""))
            view = st.radio("Layout", ["Cards", "Table"], horizontal=True,
                            index=0, key="news_layout", label_visibility="collapsed")
            if view == "Cards":
                render_cards(items, limit=60)
            else:
                if items:
                    st.dataframe(grouped_frame(items), hide_index=True,
                                 column_config={"Link": st.column_config.LinkColumn("Link")},
                                 height=460, **container_kw())

        with t_hot:
            if not hot:
                st.info("इस cycle में किसी F&O नाम से match होती खबर नहीं मिली।")
            else:
                st.caption("जिन नामों की खबर आई है (count के साथ) — expand करके पढ़ें।")
                for sym in hot[:12]:
                    rows = [n for n in items if sym in (n.get("Symbols") or [])]
                    if not rows:
                        continue
                    sents = [n.get("Sentiment") or 0 for n in rows]
                    avg = sum(sents) / max(1, len(sents))
                    with st.expander(f"{sym} · {len(rows)} headlines · avg {avg:+.2f}", expanded=False):
                        for n in rows[:6]:
                            news_card(n)

        with t_inst:
            gcount = {}
            for n in news:
                for g in (n.get("Globals") or []):
                    gcount[g] = gcount.get(g, 0) + 1
            if not gcount:
                st.info("Global instruments से जुड़ी कोई खबर इस cycle में नहीं।")
            else:
                st.markdown("".join(
                    f'<span class="chip chip-glob">{GLOBAL_LABEL.get(k, k)} · {v}</span>'
                    for k, v in sorted(gcount.items(), key=lambda x: -x[1])),
                    unsafe_allow_html=True)
                inst = st.selectbox("Instrument चुनें", sorted(gcount, key=lambda k: -gcount[k]),
                                    format_func=lambda k: GLOBAL_LABEL.get(k, k))
                render_cards([n for n in news if inst in (n.get("Globals") or [])], limit=30)

        with t_macro:
            macro = [n for n in news if n.get("MarketWide")]
            st.caption("RBI / FII-DII / inflation / expiry जैसी macro खबरें — ये पूरे F&O "
                       "universe पर लागू होती हैं।")
            render_cards(macro, limit=30) if macro else st.info("कोई macro headline नहीं।")

        with t_search:
            st.markdown("**किसी भी symbol/instrument की ताज़ा खबर सीधे खींचें**")
            q1, q2 = st.columns([1.4, 1])
            with q1:
                target = st.selectbox("F&O symbol", hot[:80] or
                                      [f["Symbol"] for f in state.features[:40]])
            with q2:
                qlimit = st.slider("Results", 3, 10, 5)
            if st.button("🔎 Firecrawl search", **container_kw()):
                if not (cfg.firecrawl_api_key or st.session_state.get("ui_fc_key")):
                    st.warning("Firecrawl key Settings/इस expander में डालें — बिना key यह "
                               "बटन search नहीं कर सकता।")
                else:
                    from terminal.providers.firecrawl import FirecrawlProvider
                    cfg2 = build_config()
                    cfg2.firecrawl_api_key = st.session_state.get("ui_fc_key", cfg2.firecrawl_api_key)
                    fp = FirecrawlProvider(cfg2)
                    with st.spinner(f"{target} की खबरें खींची जा रही हैं …"):
                        arts = fp.company_news(target, limit=qlimit)
                    if not arts:
                        st.error(f"कोई result नहीं (error: {fp.last_error or 'empty'})")
                    else:
                        for a in arts:
                            news_card({"Headline": a["title"], "Summary": a.get("summary", ""),
                                       "Link": a.get("url", ""), "Source": "Firecrawl",
                                       "Category": "Markets", "Sentiment": 0.0,
                                       "Symbols": [target], "Time": "just now"})

